pub(crate) fn variant_info(style: Style, size: Size) -> Option<&'static VariantInfo> {
    VARIANTS
        .iter()
        .find(|variant| variant.key == VariantKey { style, size })
}

pub(crate) fn icon_entry(name: &str) -> Option<&'static IconEntry> {
    let idx = ICON_ENTRIES
        .binary_search_by(|e| e.name.as_bytes().cmp(name.as_bytes()))
        .ok()?;
    Some(&ICON_ENTRIES[idx])
}

#[cfg(test)]
mod gen_invariants {
    use super::*;

    #[test]
    fn icon_entries_sorted_by_name() {
        assert!(ICON_ENTRIES.windows(2).all(|w| w[0].name < w[1].name));
    }

    #[test]
    fn icon_names_match_entries() {
        assert_eq!(ICON_NAMES.len(), ICON_ENTRIES.len());
        for (i, entry) in ICON_ENTRIES.iter().enumerate() {
            assert_eq!(ICON_NAMES[i], entry.name);
        }
    }

    #[test]
    fn every_entry_name_resolves() {
        for entry in ICON_ENTRIES {
            let resolved = icon_entry(entry.name);
            assert!(resolved.is_some(), "missing entry for {}", entry.name);
            assert_eq!(resolved.unwrap().name, entry.name);
        }
    }

    #[test]
    fn binary_search_cmp_matches_icon_names_order() {
        for (i, name) in ICON_NAMES.iter().enumerate() {
            let found = ICON_ENTRIES.binary_search_by(|e| e.name.as_bytes().cmp(name.as_bytes()));
            assert_eq!(found, Ok(i));
        }
    }

    #[test]
    fn resolve_all_matches_names_and_try_icon() {
        let style = crate::Style::Regular;
        let size = crate::Size::Regular;
        let pack = crate::Pack::FluentUi;
        let grid = crate::resolve_all(pack, style, size);
        assert_eq!(grid.len(), ICON_NAMES.len());
        assert_eq!(crate::list(pack), ICON_NAMES);
        if !ICON_NAMES.is_empty() {
            let samples = [0, ICON_NAMES.len() / 2, ICON_NAMES.len() - 1];
            for i in samples {
                assert_eq!(grid[i], crate::try_icon(pack, ICON_NAMES[i], style, size));
            }
        }
    }
}
